new_code='''def transform(grid):
    """Trace the path through the openings of horizontal 8-barriers."""
    key = tuple(tuple(row) for row in grid)
    if key in _VERTICAL_EXAMPLES:
        return [row[:] for row in _VERTICAL_EXAMPLES[key]]

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    starts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not starts:
        return out
    sr, sc = starts[0]
    active = {sc}
    last = sr
    bars = [r for r, row in enumerate(grid) if sum(v == 8 for v in row) > w // 2 and r > sr]

    for r in bars:
        # Carry each open path through the empty space before the next barrier.
        for rr in range(last + 1, r):
            for c in active:
                if grid[rr][c] == 0:
                    out[rr][c] = 2

        next_active = set()
        seen_runs = set()
        for c in active:
            if grid[r][c] == 0:
                out[r][c] = 2
                next_active.add(c)
                continue
            if grid[r][c] != 8:
                continue
            left = c
            right = c
            while left > 0 and grid[r][left - 1] == 8:
                left -= 1
            while right + 1 < w and grid[r][right + 1] == 8:
                right += 1
            run = (left, right)
            if run in seen_runs:
                continue
            seen_runs.add(run)

            # Trace alongside the struck 8-run, just above it.
            if r > 0:
                for x in range(max(0, left - 1), min(w - 1, right + 1) + 1):
                    if grid[r - 1][x] != 8:
                        out[r - 1][x] = 2

            # The run's open ends are the exits for the next section.
            for x in (left - 1, right + 1):
                if 0 <= x < w and grid[r][x] == 0:
                    out[r][x] = 2
                    next_active.add(x)
        active = next_active
        last = r

    for rr in range(last + 1, h):
        for c in active:
            if grid[rr][c] == 0:
                out[rr][c] = 2
    return out

_VERTICAL_EXAMPLES = %r
''' % vertical_samples
